entries[277773] = { ["name"] = "Löwenaspekt", ["text"] = "Wirken in 8 sek.\nNimmt die Gestalt eines Löwen an, was die Energie der missgestalten Schöpfung auffüllt, die mit der Zeit wieder abnimmt. Sobald die Energie aufgebraucht ist, verwandelt sich die missgestalte Schöpfung in einen urzeitlichen Schleim zurück." }
