entries[277776] = { ["name"] = "Habichtaspekt", ["text"] = "Wirken in 8 sek.\nNimmt die Gestalt eines Geiers an, was die Energie der missgestalten Schöpfung auffüllt, die mit der Zeit wieder abnimmt. Sobald die Energie aufgebraucht ist, verwandelt sich die missgestalte Schöpfung in einen urzeitlichen Schleim zurück." }
